# Candidate (B2) for TASK-BANK-010 (iso20022_pacs008_wrap)
def build_request(data):
    return {
        'path': '/v2/banking/iso20022_pacs008_wrap/task-bank-010',
        'body': {
            'pacs008_document': {
                'amount_subunits': int(data['amount_cents']),
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': 'unverified_route_task-bank-010',
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': 'dropped-idem-b2-task-bank-010'
        }
    }

def execute_debit(data):
    return build_request(data)

